<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/health_network_v590.php';if(!hn590_bool('health_network_v590_public_labs',true)){http_response_code(404);exit('Lab directory unavailable.');}$id=(int)($_GET['id']??$_POST['lab_id']??0);$lab=hn590_lab($id);if(!$lab||$lab['status']!=='active'||!$lab['verified']){http_response_code(404);exit('Lab not found.');}$flash='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$u=hn590_require_login('/lab.php?id='.$id);$bid=hn590_create_lab_booking((int)$u['id'],$id,(int)($_POST['test_id']??0),(string)($_POST['scheduled_at']??''),!empty($_POST['home_collection']),trim((string)($_POST['collection_address']??'')));$flash='Lab booking request submitted. Reference #'.$bid.'.';}catch(Throwable $e){$error=$e->getMessage();}}$tests=hn590_lab_tests($id);hn590_track('lab_view','lab',$id);hn590_public_header($lab['name'],'Book published diagnostic tests and sample collection.');
?><main><section class="hn590-provider-hero lab"><div class="hn590-shell"><a href="/labs.php">← Diagnostic Labs</a><div class="hn590-provider-title"><div class="hn590-bigicon blue">◫</div><div><span class="hn590-badge blue">VERIFIED LAB</span><h1><?=e($lab['name'])?></h1><p>⌖ <?=e($lab['address']?:$lab['area'])?> · <?=e($lab['phone']?:'Portal contact')?></p></div></div><div class="hn590-pills"><span><?=$lab['home_collection']?'✓ Home collection available':'Visit lab for collection'?></span></div></div></section><section class="hn590-section"><div class="hn590-shell"><?php if($flash):?><div class="hn590-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="hn590-alert err"><?=e($error)?></div><?php endif;?><div class="hn590-test-list"><?php if(!$tests):?><div class="hn590-empty">No tests published yet.</div><?php endif;?><?php foreach($tests as $t):?><article><div><small><?=e($t['category']?:'Diagnostic Test')?></small><h3><?=e($t['name'])?></h3><p><?=e($t['sample_type']?:'Sample details provided by lab')?> · Estimated turnaround <?=max(1,(int)$t['turnaround_hours'])?>h</p><?php if($t['preparation_text']):?><p class="prep"><b>Preparation:</b> <?=e($t['preparation_text'])?></p><?php endif;?></div><div><strong><?=hn590_money((float)$t['price'])?></strong><details><summary>Book Test</summary><form method="post" class="hn590-order-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="lab_id" value="<?=$id?>"><input type="hidden" name="test_id" value="<?=(int)$t['id']?>"><label>Preferred date & time<input type="datetime-local" name="scheduled_at" required min="<?=e(date('Y-m-d\TH:i'))?>"></label><?php if($lab['home_collection']&&$t['home_collection']):?><label class="check"><input type="checkbox" name="home_collection" value="1"> Request home sample collection</label><label>Collection address<textarea name="collection_address"></textarea></label><?php endif;?><button class="hn590-btn primary">Request Booking</button></form></details></div></article><?php endforeach;?></div><div class="hn590-safety-card"><b>Diagnostic safety</b><p>Test listings and turnaround times are operational information. Interpretation, diagnosis and treatment decisions must be made by qualified healthcare professionals.</p></div></div></section></main><?php hn590_public_footer();?>
